/// <summary>
/// Class responsible for creating CSD transfer orders catering for scenario having one to one mapping.
/// </summary>
class METCreateCSDTransferOrder_TOSOOneToOne extends METCreateCSDTransferOrder
{
    Map custStagingLaneMap;
    METNumberOfCustomers  custCurrentPosition;


}

Method.Source:
/// <summary>
/// Sets supply warehouse.
/// </summary>
protected void setSupplyWarehouse()
{
    supplyWarehouse = metSalesLine.SupplyingWarehouse;
}

/// <summary>
/// Initializes class variables.
/// </summary>
protected void init()
{
    super();


    if (doSetStagingLane)
    {
        if (!this.parmContinueFromStagingLane())
        {
            custCurrentPosition = toInventLocation.METCustStartingPosition;
        }
        else
        {
            if (!METStagingLanePositionCounter::find(toInventLocation.InventLocationId).RecId)
            {
                this.createMETStagingLanePositionCounter(toInventLocation);

                custCurrentPosition = toInventLocation.METCustStartingPosition;
            }
            else
            {
                custCurrentPosition = METStagingLanePositionCounter::find(toInventLocation.InventLocationId).NextStagingLane;
            }
        }

        custStagingLaneMap = new Map(Types::String, Types::Integer);
    }

    IstransferSOTO = true;
}

/// <summary>
/// Initializes transfer order records.
/// </summary>
protected void initTransferOrder()
{
    super();

    if (doSetStagingLane)
    {
        this.setStagingLane();
    }

    this.applyRules();
    this.addToTransferOrderMap();

}

/// <summary>
/// Initializes transfer table.
/// </summary>
protected void initTransferTable()
{
    super();

    //This step is done to make this transfer order unique in transferOrderMap.
    //It will be later replaced with transfer Id.
    transferTable.TransferId = salestable.SalesId;
    metTransferTable.SalesId = salestable.SalesId;
    metTransferTable.InternalCustomer = salestable.CustAccount;
    metTransferTable.Route = metSalesTable.SecondRoute;
    metTransferTable.RouteStopNum = metSalesTable.SecondRouteStopNum;
    metTransferTable.Door = metSalesTable.DoorNum;
    metTransferTable.RouteStopIdentifier = metSalesTable.OriginalSecondRouteStopIdentifier;
    metTransferTable.RouteIdentifier = metSalesTable.OriginalSecondRouteIdentifier;
}

/// <summary>
/// Initializes transfer line.
/// </summary>
protected void initTransferLine()
{
    super();

    //This step is done to make this transferLine record unique in transferOrderMap.
    //Only one sales order record will be catered per transfer order.
    //It will be later replaced with transfer Id.
    transferLine.TransferId = salestable.SalesId;
    metTransferLine = transferLine.metInventTransferLine();

    metTransferLine.SalesId = salesLine.SalesId;
    metTransferLine.SalesLineTransId = salesLine.InventTransId;

    transferLine.metPackMETInventTransferLine(metTransferLine, true);
}

/// <summary>
/// Sets staging lane on transfer orders..
/// </summary>
protected void setStagingLane()
{
    METNumberOfCustomers stagingLane;

    if (!doSetStagingLane && metTransferTable.StagingLane)
    {
        return;
    }

    if (custStagingLaneMap.exists(salestable.CustAccount))
    {
        stagingLane = custStagingLaneMap.lookup(salestable.CustAccount);
    }
    else
    {
        stagingLane = custCurrentPosition;
        custCurrentPosition++;
    }

    metTransferTable.StagingLane = int2Str(stagingLane);
    transferTable.metPackMETInventTransferTableExt(metTransferTable);
    custStagingLaneMap.insert(salestable.CustAccount, stagingLane);
}

/// <summary>
/// Post create method as an extension point.
/// </summary>
protected void postCreate()
{
    this.updateTransferOrderRefOnSalesLine();
    super();
    this.updateTransferLineMarking();
}

/// <summary>
/// Updates transfer order reference on sales lines.
/// </summary>
protected void updateTransferOrderRefOnSalesLine()
{
    METSalesLine          metSalesLineLocal;
    SalesLine             salesLineLocal;
    METInventTransferLine metTransferLineLocal;
    InventTransferLine    transferLineLocal;

    SysDaQueryObject metTransferLineObject = new SysDaQueryObject(metTransferLineLocal);
    SysDaQueryObject salesLineQueryObject = new SysDaQueryObject(salesLineLocal);
    SysDaQueryObject transferLineQueryObject = new SysDaQueryObject(transferLineLocal);
    SysDaUpdateObject updatedObject = new SysDaUpdateObject(metSalesLineLocal);

    salesLineQueryObject.whereClause(new SysDaEqualsExpression(
            new SysDaFieldExpression(salesLineLocal, fieldStr(SalesLine, RecId)),
            new SysDaFieldExpression(metSalesLineLocal, fieldStr(METSalesLine, SalesLine))));

    metTransferLineObject.whereClause(new SysDaEqualsExpression(
            new SysDaFieldExpression(salesLineLocal, fieldStr(SalesLine, InventTransId)),
            new SysDaFieldExpression(metTransferLineLocal, fieldStr(METInventTransferLine, SalesLineTransId))
        ).and(  new SysDaEqualsExpression(
            new SysDaFieldExpression(salesLineLocal, fieldStr(SalesLine, SalesId)),
            new SysDaFieldExpression(metTransferLineLocal, fieldStr(METInventTransferLine, SalesId))
        )));

    transferLineQueryObject.whereClause(new SysDaEqualsExpression(
            new SysDaFieldExpression(transferLineLocal, fieldStr(InventTransferLine, RecId)),
            new SysDaFieldExpression(metTransferLineLocal, fieldStr(METInventTransferLine, InventTransferLine))
        ).and(this.getTransferLineExpression(transferLineLocal)));

    metTransferLineObject.joinClause(SysDaJoinKind::InnerJoin, transferLineQueryObject);
    salesLineQueryObject.joinClause(SysDaJoinKind::InnerJoin, metTransferLineObject);

    updatedObject.joinClause(SysDaJoinKind::InnerJoin, salesLineQueryObject);
    updatedObject.settingClause()
                 .add(fieldStr(METSalesLine, InventTransIdReceive),
                      new SysDaFieldExpression(transferLineLocal, fieldStr(InventTransferLine, InventTransIdReceive)))
                 .add(fieldstr(METSalesLine, TransferOrderNumber),
                      new SysDaFieldExpression(transferLineLocal, fieldstr(InventTransferLine, TransferId)));

    ttsbegin;
    new SysDaUpdateStatement().update(updatedObject);
    ttscommit;
}

/// <summary>
/// Updates staging lane.
/// </summary>
protected void updateStagingLane()
{
    METNextCustStartingPosition nextCustStartingPosition;
    SetEnumerator setEnum;

    setEnum = transferIdSet.getEnumerator();

    while (setEnum && setEnum.moveNext())
    {
        InventTransferLine        transferLineLocal;
        InventTransferTable       transferTableLocal;
        METInventTransferTableExt metTransferTableLocal;
        METInventTransferLine     metTransferLineLocal;
        METSalesTable             metSalesTableUpd;

        InventTransferId transferId = setEnum.current();

        select firstonly SalesId from metTransferLineLocal
        join RecId from transferLineLocal
            where transferLineLocal.RecId == metTransferLineLocal.InventTransferLine
            &&    transferLineLocal.TransferId == transferId
        join RecId from transferTableLocal
            where transferTableLocal.TransferId == transferLineLocal.TransferId
        join StagingLane from metTransferTableLocal
            where metTransferTableLocal.InventTransferTable ==  transferTableLocal.RecId;

        if (metTransferLineLocal.SalesId && metTransferTableLocal.StagingLane)
        {
            ttsbegin;
            metSalesTableUpd.clear();
            metSalesTableUpd.readPast(true);

            metSalesTableUpd = METSalesTable::findBySalesId(metTransferLineLocal.SalesId, true);

            if (metSalesTableUpd)
            {
                metSalesTableUpd.StagingLaneId = metTransferTableLocal.StagingLane;
                metSalesTableUpd.update();
            }
            ttscommit;
        }

        nextCustStartingPosition = any2Int(metTransferTableLocal.StagingLane);
    }

    if (nextCustStartingPosition && doSetStagingLane && this.parmContinueFromStagingLane())
    {
        ttsbegin;
        METStagingLanePositionCounter stagingLanePositionCounter;
        stagingLanePositionCounter = METStagingLanePositionCounter::find(toInventLocation.InventLocationId, true);
        if (stagingLanePositionCounter)
        {
            stagingLanePositionCounter.NextStagingLane = nextCustStartingPosition + 1;
            stagingLanePositionCounter.update();
        }
        ttscommit;
    }

}

/// <summary>
/// Updates transfer line marking.
/// </summary>
private void updateTransferLineMarking()
{
    SetEnumerator setEnum;

    setEnum = transferIdSet.getEnumerator();

    while (setEnum && setEnum.moveNext())
    {
        InventTransferLine    transferLineLocal;
        InventTransferId      transferId;

        transferId = setEnum.current();

        while select transferLineLocal
            where transferLineLocal.TransferId == transferId
        {
            transferLineLocal.metCheckAndUpdateMarking();
        }

    }
}
